-- Bond schedule for the Info tab, from Seventh Judicial Circuit Administrative Order 2/28/25
-- (misdemeanor & felony bond schedule, filed Feb 28 2025). 70 charges plus the order's rules.
-- Run once in the Sheriff's Office Supabase project (SQL Editor), after schema.sql. Running it again adds nothing twice.
insert into public.info_rows (section, sort, data)
select 'bond', v.sort, v.data::jsonb
from (values
